window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["streaming"]={"title":"流式输出：把一次生成变成可取消、可恢复的事件协议","subtitle":"从 token、UTF-8 字节块与 SSE 事件，到 TTFT、背压、结构缓冲、安全审查和最终提交。","thesis":"流式不会减少模型完成整段回答的总计算，它把结果分段送达，改善首字可见时间和交互控制。可靠实现必须把<b>字节、字符、token、事件和业务提交</b>分开，并处理取消、背压、重连、半截结果与副作用。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"排队 120ms","rule":"首字约 400ms","steps":"400+39×50=2350ms","interpretation":"只有取消信号传播到模型服务"}}],"formulas":[{"id":"streaming-latency","section":4,"formulaIndex":1,"symbols":[{"name":"TTFT","meaning":"请求到首 token 可见的时间","evidence":"从请求发出到首 token 可见的时间"},{"name":"Q","meaning":"请求排队时间","evidence":"Q 是排队时间"},{"name":"P","meaning":"输入前缀的预填充时间","evidence":"处理输入前缀的预填充时间"},{"name":"D","meaning":"首步解码时间","evidence":"D 是首步解码时间"},{"name":"E","meaning":"完整响应完成时间","evidence":"E 是完整完成时间"},{"name":"N","meaning":"输出 token 总数","evidence":"N 是输出 token 总数"},{"name":"TPOT","meaning":"每个后续 token 的平均解码间隔","evidence":"每个 token 的平均解码间隔"},{"name":"X","meaning":"传输与前端渲染耗时","evidence":"网络传输与前端渲染耗时"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"流式输出把生成过程包装成逐步送达、可取消并有终态的事件流。","evidence":"流式输出输入正在生成的 token 和请求生命周期"},"problem":{"answer":"它改善用户等待形状和交互控制，而不是减少完整生成工作量。","evidence":"流式改善的是等待形状，不是总工作量"},"inputOutput":{"answer":"输入生成 token 与生命周期，输出增量事件和最终状态。","evidence":"输出逐步可见的增量事件及最终状态"},"mechanism":{"answer":"服务在增量可用时立即发送，客户端边解码边安全展示。","evidence":"提前传送已产生内容"},"interpretation":{"answer":"首字快表示可见时间短，不表示最终响应更快或已经完成。","evidence":"改善首字和取消体验"},"boundary":{"answer":"前缀可见不能替代 done、完整校验和业务提交。","evidence":"不能解释为请求已经完成或通过校验"}},{"section":2,"definition":{"answer":"token、UTF-8 字节、字符、网络块和协议事件由不同层决定边界。","evidence":"token、字节块、字符和事件不是同一边界"},"problem":{"answer":"它避免直接把网络 chunk 当成字符、token 或完整 JSON 解析。","evidence":"网络 chunk 不能直接当成一个字符或一个模型 token"},"inputOutput":{"answer":"输入 token、字节块和协议帧，输出完整字符与类型化事件。","evidence":"输出完整字符与类型化事件"},"mechanism":{"answer":"客户端跨块保留 UTF-8 和协议解析状态再组装内容。","evidence":"客户端必须跨块保留解码状态"},"interpretation":{"answer":"TCP chunk 仅表示传输分片，不代表语义或提交单位。","evidence":"TCP chunk 只表示一次传输分片"},"boundary":{"answer":"网络分片不能直接作为 JSON 或业务提交边界。","evidence":"不能作为 JSON 或业务提交边界"}},{"section":3,"definition":{"answer":"流式事件协议用类型、序号、请求标识和终态表达完整生命周期。","evidence":"事件协议要表达生命周期而非只发字符串"},"problem":{"answer":"它让客户端区分正常完成、取消、错误、重连和连接中断。","evidence":"怎样区分正常结束、取消和错误"},"inputOutput":{"answer":"输入请求状态和各类增量，输出带 id、sequence、版本与终态的事件流。","evidence":"输出带 request id、sequence、版本和终态的事件流"},"mechanism":{"answer":"客户端按 sequence 去重推进状态，服务明确发送 done 或错误终态。","evidence":"客户端按序去重和状态机处理"},"interpretation":{"answer":"只有 done 且最终校验通过才表示 completed。","evidence":"只有显式 done 且最终校验通过才完成"},"boundary":{"answer":"EOF 可能来自断网、崩溃或取消，不能推断正常完成。","evidence":"EOF 只表示连接关闭"}},{"section":4,"definition":{"answer":"时间线案例把排队、预填充、首 token、逐 token 解码和完成拆开。","evidence":"一次 40-token 回答的时间线"},"problem":{"answer":"它计算用户何时看到首字、完整完成以及取消能节省多少工作。","evidence":"用户何时看见、何时完成"},"inputOutput":{"answer":"输入排队、预填充、token 数和 TPOT，输出 TTFT、完成与浪费。","evidence":"输出 TTFT、完整时间与取消后浪费"},"mechanism":{"answer":"首字为排队加预填充和首步，完成再加后续 token 间隔。","evidence":"首字约 400ms"},"interpretation":{"answer":"0.4 秒开始阅读不表示 2.4 秒的完整计算已经消失。","evidence":"完整约 2.35 到 2.4 秒"},"boundary":{"answer":"取消只有传播至模型服务时才停止剩余 token 计算。","evidence":"只有取消信号传播到模型服务"}},{"section":5,"definition":{"answer":"背压是慢消费者把容量限制反馈给快生产者的流量控制。","evidence":"背压是慢消费者对快生产者的反馈"},"problem":{"answer":"它防止浏览器渲染慢时缓冲无限增长并导致延迟或断连。","evidence":"服务器每秒发 100 个 delta，会发生什么"},"inputOutput":{"answer":"输入生产消费速率和水位，输出批量、暂停、合并或取消。","evidence":"输出批量渲染、暂停、合并或取消决策"},"mechanism":{"answer":"压力从 DOM、客户端、网关逐层传播到上游读取。","evidence":"必须把压力逐层传回网关和上游"},"interpretation":{"answer":"缓冲增长和延迟扩大表示消费速度长期低于生产速度。","evidence":"缓冲不断增长，内存和延迟上升"},"boundary":{"answer":"工具事件不能像文本 delta 一样随意合并，必须保序。","evidence":"工具事件则必须保持顺序与语义"}},{"section":6,"definition":{"answer":"取消、超时和重连以 request id、序号、日志和幂等键保持一致状态。","evidence":"取消、超时和重连都需要幂等语义"},"problem":{"answer":"它防止前端停止后模型或退款工具仍运行，以及重连重复执行。","evidence":"用户点停止后，为什么工具仍可能完成退款"},"inputOutput":{"answer":"输入 id、sequence、取消、幂等和日志，输出取消、完成、未知或重放状态。","evidence":"输出已取消、已完成、未知或可重放状态"},"mechanism":{"answer":"逐层传播取消，超时先查动作状态，重连按序号去重重放。","evidence":"超时后先查询动作状态再重试"},"interpretation":{"answer":"停止显示只表示 UI 终止，不表示事务已撤销。","evidence":"前端停止显示不等于事务撤销"},"boundary":{"answer":"已提交副作用只能补偿或人工处理，不能假装取消成功。","evidence":"需要补偿或人工处理"}},{"section":7,"definition":{"answer":"结构化流必须缓冲到完整接受态并通过 schema、事实和权限校验。","evidence":"结构化输出必须缓冲到接受态"},"problem":{"answer":"它防止看到半截 amount 或 JSON 前缀时过早执行工具。","evidence":"为什么不能提前执行"},"inputOutput":{"answer":"输入 tool_call_delta，输出完整且经全部校验的参数。","evidence":"输出完整接受态并经 schema、事实和权限校验的参数"},"mechanism":{"answer":"客户端只组装前缀，等待接受态后再校验并提交。","evidence":"客户端只能组装和预览"},"interpretation":{"answer":"前缀合法只表示仍可能完成，不表示数值和对象已经定稿。","evidence":"数字、字符串和对象前缀都可能继续变化"},"boundary":{"answer":"中断回答要标记 interrupted，不能混作完整训练或评测样本。","evidence":"不能混入完整答案的训练或评测"}},{"section":8,"definition":{"answer":"增量安全渲染跨块累积文本并在安全单元上解析、扫描和展示。","evidence":"安全、Markdown 与 UI 都有增量陷阱"},"problem":{"answer":"它处理无害 delta 拼接后形成脚本、链接或敏感信息的问题。","evidence":"拼接后为什么可能形成脚本、链接或敏感信息"},"inputOutput":{"answer":"输入跨块文本和风险策略，输出安全渲染与审核后的展示单元。","evidence":"输出纯文本累积、安全 Markdown/HTML 和审核后的展示单元"},"mechanism":{"answer":"扫描器保留跨块窗口，前端累积纯文本后用安全渲染器。","evidence":"扫描器维护跨块窗口"},"interpretation":{"answer":"单个块无害不能说明拼接后的完整内容无害。","evidence":"单个 delta 看起来无害"},"boundary":{"answer":"高风险领域可延迟审核，流式并非所有场景默认更好。","evidence":"流式并非所有场景默认更好"}},{"section":9,"definition":{"answer":"流式可靠性评测同时覆盖性能、取消、恢复、缓冲、安全和最终质量。","evidence":"评测应覆盖完成、取消和故障路径"},"problem":{"answer":"它补足漂亮平均 TTFT 无法证明完成和故障路径可靠的问题。","evidence":"还缺哪些指标才能证明流式可靠"},"inputOutput":{"answer":"输入日志、切片和故障注入，输出性能、恢复、资源与质量指标。","evidence":"输出 TTFT、TPOT、完成、取消传播、浪费 token、恢复、缓冲、帧率和最终质量"},"mechanism":{"answer":"按网络设备并发切片并注入断流、乱序、重复、超时和重启。","evidence":"网络设备并发切片和故障注入"},"interpretation":{"answer":"成功需同时满足及时、安全、可取消、正确提交和故障显式。","evidence":"成功必须同时证明安全增量及时"},"boundary":{"answer":"故障不得静默伪装成完成，最终状态和副作用必须验收。","evidence":"故障不伪装完成"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分字节块/token/事件；计算 TTFT 与完成时间；设计可恢复事件协议；处理背压、取消与安全提交。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>流式改善的是等待形状，不是总工作量<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">用户 400ms 看见第一个字，为什么服务器仍可能计算 8 秒？</p><p>流式输出输入正在生成的 token 和请求生命周期，输出逐步可见的增量事件及最终状态。它提前传送已产生内容，改善首字和取消体验，却不减少生成完整序列所需的模型工作；前缀可见不能解释为请求已经完成或通过校验。</p><p>非流式等完整答案生成后一次返回；流式在 token 或文本增量可用时立即发送。用户可提前阅读、取消或看到工具进度，但模型仍需生成全部 token，网络事件和前端渲染还增加额外开销。</p><p>因此分别测首字时间 TTFT、token 间隔 TPOT、完整时间 E2E 和取消生效时间。只宣传“首字快”可能掩盖最终更慢或答案半途失败。</p><div class=\"dd-note\"><b>核心边界：</b>可见不等于完成，前缀合法不等于最终结果有效，客户端断开也不等于上游计算已停止。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>token、字节块、字符和事件不是同一边界<span class=\"dd-badge eng\">协议</span></h2><p class=\"dd-lead\">为什么一个网络 chunk 不能直接当成一个字符或一个模型 token？</p><p>增量解码输入模型 token、UTF-8 字节块和协议帧，输出完整字符与类型化事件。tokenizer、字符编码、网络切块和应用协议各自决定边界，客户端必须跨块保留解码状态；TCP chunk 只表示一次传输分片，不能作为 JSON 或业务提交边界。</p><p>模型产生 token，服务端把 token 解码成 UTF-8 字节，再按网络和缓冲策略切块；一个中文字符可能跨字节块，一个 token 可能含多个字符，JSON 转义也可跨事件。客户端必须用增量 UTF-8 解码器，并以协议事件而非 TCP chunk 解析。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>单位</th><th>由谁决定</th><th>可否作为提交边界</th></tr></thead><tbody><tr><td>token</td><td>模型 tokenizer</td><td>否，可能半个词/结构</td></tr><tr><td>字节 chunk</td><td>运行时/网络</td><td>否，可能拆 UTF-8</td></tr><tr><td>字符/文本 delta</td><td>增量解码器</td><td>只适合展示</td></tr><tr><td>协议事件</td><td>应用 schema</td><td>按事件语义判断</td></tr><tr><td>done + 校验</td><td>业务层</td><td>可成为最终提交边界</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>事件协议要表达生命周期而非只发字符串<span class=\"dd-badge eng\">设计</span></h2><p class=\"dd-lead\">连接中途失败时，客户端怎样区分正常结束、取消和错误？</p><p>事件协议输入请求状态与文本、工具、使用量和错误增量，输出带 request id、sequence、版本和终态的事件流。客户端按序去重和状态机处理，只有显式 done 且最终校验通过才完成；EOF 只表示连接关闭，不能推断正常结束。</p><p>定义 <code>start</code>、<code>text_delta</code>、<code>tool_delta</code>、<code>tool_complete</code>、<code>usage</code>、<code>error</code>、<code>cancelled</code>、<code>done</code>。每条流有 request id、递增 sequence、协议版本和可选 event id；只有 done 且最终校验通过才标记 completed。</p><p>SSE 简单、自动重连但单向；WebSocket 双向且状态复杂；HTTP 分块通用但需自定义帧。选择取决于交互，不改变必须明确帧边界、顺序、幂等与终态。</p><div class=\"dd-note warn\"><b>EOF 不是 done。</b>　连接关闭可能来自网络、代理、服务崩溃或用户取消，不能把已收到前缀自动当完整答案。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：一次 40-token 回答的时间线<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">排队 120ms、预填充 280ms、每 token 50ms，用户何时看见、何时完成？</p><p>案例输入排队、预填充、token 数和 TPOT，输出 TTFT、完整时间与取消后浪费。首字约 400ms，四十 token 完整约 2.35 到 2.4 秒；一秒取消时约显示十二个 token。只有取消信号传播到模型服务，剩余二十八个 token 的计算才会停止。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 250\" role=\"img\" aria-label=\"流式请求的排队、预填充、首 token、增量、取消和完成时间线\"><line x1=\"35\" y1=\"128\" x2=\"680\" y2=\"128\" stroke=\"#6b7484\" stroke-width=\"2\"/><rect x=\"35\" y=\"92\" width=\"90\" height=\"36\" fill=\"#c77b72\"/><text x=\"80\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">排队 120ms</text><rect x=\"125\" y=\"92\" width=\"170\" height=\"36\" fill=\"#d3a05a\"/><text x=\"210\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">prefill 280ms</text><circle cx=\"295\" cy=\"128\" r=\"7\" fill=\"#4f9d78\"/><text x=\"295\" y=\"157\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">TTFT≈400ms</text><rect x=\"302\" y=\"92\" width=\"330\" height=\"36\" fill=\"#6b8cbe\"/><text x=\"467\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">40 token × 50ms ≈ 2000ms</text><circle cx=\"632\" cy=\"128\" r=\"7\" fill=\"#4f9d78\"/><text x=\"632\" y=\"157\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">done≈2400ms</text><path d=\"M390,128 L390,194\" stroke=\"#c77b72\" stroke-dasharray=\"4 3\"/><text x=\"390\" y=\"211\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">若 1s 取消：约已显示 12 token；必须向上游传播 abort</text></svg><figcaption>图 1　流式把 2.4 秒的单次等待改成 0.4 秒开始阅读，但完整计算并未消失。</figcaption></figure><div class=\"dd-formula\" data-formula-id=\"streaming-latency\"><math display=\"block\" aria-label=\"首 token 时间 TTFT 约等于排队 Q 加预填充 P 加首步解码 D；完成时间 E 约等于 TTFT 加 N 减一乘每 token 时间 TPOT，再加传输渲染 X\"><mtable><mtr><mtd><mi>TTFT</mi><mo>≈</mo><mi>Q</mi><mo>+</mo><mi>P</mi><mo>+</mo><mi>D</mi></mtd></mtr><mtr><mtd><mi>E</mi><mo>≈</mo><mi>TTFT</mi><mo>+</mo><mo>(</mo><mi>N</mi><mo>−</mo><mn>1</mn><mo>)</mo><mi>TPOT</mi><mo>+</mo><mi>X</mi></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>TTFT</code> 是从请求发出到首 token 可见的时间，<code>Q</code> 是排队时间，<code>P</code> 是处理输入前缀的预填充时间，<code>D</code> 是首步解码时间；<code>E</code> 是完整完成时间，<code>N</code> 是输出 token 总数，<code>TPOT</code> 是首 token 之后每个 token 的平均解码间隔，<code>X</code> 是网络传输与前端渲染耗时。它是容量规划近似，真实服务还会受批处理和事件抖动影响。</p><p>N=40、TPOT=50ms 时完成约 400+39×50=2350ms，再加传输接近 2.4s。若用户在 1s 取消，已解码约 (1000−400)/50=12 token；若取消未传到模型服务，剩余 28 token 仍浪费成本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>背压是慢消费者对快生产者的反馈<span class=\"dd-badge eng\">流控</span></h2><p class=\"dd-lead\">浏览器每秒只能渲染 20 次，服务器每秒发 100 个 delta，会发生什么？</p><p>背压控制输入生产速率、消费速率和缓冲水位，输出批量渲染、暂停、合并或取消决策。慢消费者必须把压力逐层传回网关和上游；若上游不能暂停，就用有界队列并超限取消。文本可合并，工具事件则必须保持顺序与语义。</p><p>缓冲不断增长，内存和延迟上升，最终断连。客户端可按动画帧或词组批量渲染；中间层设置高水位、暂停读取或合并文本 delta；服务端限制每流缓冲并在超限时取消。</p><p>背压要逐层传播：DOM 慢→客户端读取慢→网关发送受阻→应用暂停读取上游；若模型 API 不支持暂停，至少限制缓冲并取消。工具事件不能与文本随意合并，必须保持事件语义。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>症状</th><th>原因</th><th>控制</th></tr></thead><tbody><tr><td>前端卡顿</td><td>每 token 重排</td><td>16–50ms 批量渲染</td></tr><tr><td>内存增长</td><td>无界队列</td><td>高水位和取消</td></tr><tr><td>延迟越来越大</td><td>代理缓冲/慢客户端</td><td>禁缓冲、心跳、流控</td></tr><tr><td>事件乱序</td><td>并发通道合并</td><td>sequence 与单写者</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>取消、超时和重连都需要幂等语义<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">用户点停止后，为什么工具仍可能完成退款？</p><p>取消与重连输入 request id、sequence、取消信号、幂等键和动作日志，输出已取消、已完成、未知或可重放状态。取消须传播到模型与工具，超时后先查询动作状态再重试；前端停止显示不等于事务撤销，已提交副作用需要补偿或人工处理。</p><p>取消信号可能只停止前端显示，没有中止模型或已发出的工具请求。每层接收 AbortSignal/取消 token，工具动作前检查当前状态；不可逆动作使用幂等键和提交日志。超时后结果未知，重试必须先查询动作状态。</p><p>SSE 自动重连可携 Last-Event-ID，服务端从短期事件日志重放；客户端按 request id + sequence 去重。若无法重放，明确启动新请求，不把两条回答拼接。连接恢复也不能重复执行 tool_complete。</p><div class=\"dd-note warn\"><b>展示取消不等于事务撤销。</b>　已提交副作用需补偿或人工处理，协议必须如实呈现状态。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>结构化输出必须缓冲到接受态<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">工具参数已经流出 {\"amount\":12，为什么不能提前执行？</p><p>结构缓冲输入 tool_call_delta，输出完整接受态并经 schema、事实和权限校验的参数。数字、字符串和对象前缀都可能继续变化，客户端只能组装和预览；半截回答必须标记 interrupted，不能混入完整答案的训练或评测。</p><p>数字还可能变成 120，字符串可能未闭合，对象也可能追加字段。结构化 delta 可用于预览或进度，但执行必须等待完整对象、schema、事实和权限校验。服务可发送专门 tool_call_delta，客户端只组装，不解释半截 JSON。</p><p>同理，流式正文中的早期引用可能在后文被否定；持久化最终答案应存原始事件与完成状态，半截回答标记 interrupted，不与完整回答混用训练或评测。</p><div class=\"dd-note warn\"><b>安全审查有时间边界。</b>　只检查单个 chunk 会漏跨块攻击；等全文再检查又失去实时性。可做增量缓冲审查，并对高风险内容延迟展示。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>安全、Markdown 与 UI 都有增量陷阱<span class=\"dd-badge eng\">前端</span></h2><p class=\"dd-lead\">单个 delta 看起来无害，拼接后为什么可能形成脚本、链接或敏感信息？</p><p>增量安全渲染输入跨块文本和内容风险策略，输出纯文本累积、安全 Markdown/HTML 和审核后的展示单元。扫描器维护跨块窗口，前端不能逐块 innerHTML；高风险领域可延迟到句段或全文审核，流式并非所有场景默认更好。</p><p>Markdown 链接、HTML 标签、代码围栏和敏感模式可跨事件。先把 delta 当纯文本累积，使用安全渲染器；不要将未完成 HTML 注入 DOM。安全扫描维护跨块窗口，工具和外部文档内容标记为不可信。</p><p>用户看到的前缀会影响行为，即使最终系统删除或修正。医疗、金融和高风险指导可先缓冲到句子/段落或完整审查；流式不是所有场景默认更好。无障碍读屏还需要避免每个 token 触发朗读。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>风险</th><th>错误做法</th><th>安全做法</th></tr></thead><tbody><tr><td>XSS/Markdown</td><td>逐块 innerHTML</td><td>纯文本累积后安全渲染</td></tr><tr><td>跨块敏感词</td><td>每块独立扫描</td><td>滑动窗口/句级缓冲</td></tr><tr><td>高风险误导</td><td>立即展示未审查前缀</td><td>延迟到审核单元</td></tr><tr><td>读屏噪声</td><td>token 级 aria 更新</td><td>语义块与节流</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测应覆盖完成、取消和故障路径<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">平均 TTFT 很漂亮，还缺哪些指标才能证明流式可靠？</p><p>流式评测输入端到端事件日志、网络设备并发切片和故障注入，输出 TTFT、TPOT、完成、取消传播、浪费 token、恢复、缓冲、帧率和最终质量。成功必须同时证明安全增量及时、取消节省工作、done 后提交且故障不伪装完成。</p><p>测 p50/p95/p99 TTFT、TPOT、完成时间、事件间隙、取消传播延迟、取消后浪费 token、中断率、重连恢复率、重复事件、缓冲峰值、前端帧率和最终质量。按输出长度、网络、代理、设备和并发切片。</p><p>故障注入：UTF-8 跨块、事件截断、代理缓冲、乱序、重复、模型错误、工具超时、客户端断网与服务器重启。验收最终状态和副作用，而不只看文本是否“差不多显示”。</p><div class=\"dd-note\"><b>成功定义：</b>用户及时看到安全增量；取消确实节省后续工作；完整结果仅在 done+验证后提交；故障不会静默伪装成完成。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">流式是一种状态协议与资源控制，不是把字符串切碎这么简单。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>流式减少总生成计算</td><td>主要改善首字和可取消性，完整 token 仍要算</td></tr><tr><td>一个 chunk 就是一个 token</td><td>网络、字节、字符和 token 边界不同</td></tr><tr><td>断连等于正常完成</td><td>只有显式 done 与最终校验代表完成</td></tr><tr><td>点停止就停止成本</td><td>取消必须传播到上游和工具</td></tr><tr><td>结构前缀合法即可执行</td><td>需接受态、schema、事实和权限全部通过</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>tokenization、自回归解码、HTTP/SSE、UTF-8</td></tr><tr><td><b>本页核心</b></td><td>事件协议、TTFT/TPOT、背压、取消、重连与提交</td></tr><tr><td>输出</td><td>结构化输出、约束解码、工具调用</td></tr><tr><td>服务</td><td>推理优化、部署、可观测性与安全护栏</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>为流分配 request id 与序号</li><li>增量解码 token/字节为类型化事件</li><li>客户端按背压安全渲染</li><li>取消沿链路传播并保护副作用</li><li>仅在 done+校验后提交最终结果</li><li>用故障注入和端到端指标回归</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>40-token 示例的 TTFT 和完成时间约多少？</li><li>为什么网络 chunk 不能直接 JSON.parse？</li><li>EOF 为什么不是完成？</li><li>背压应如何处理？</li><li>工具参数何时可执行？</li><li>假设“流式输出：把一次生成变成可取消、可恢复的事件协议”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>TTFT 约 400ms，完整约 2.35–2.4s。</li><li>它可能拆开 UTF-8、转义或结构，必须按事件增量解码。</li><li>可能是断网、崩溃、取消或代理关闭，需显式 done。</li><li>批量渲染、有界缓冲、暂停/合并读取并向上游传播或取消。</li><li>完整接受态后通过 schema、事实、业务和权限校验时。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://html.spec.whatwg.org/multipage/server-sent-events.html\" target=\"_blank\" rel=\"noopener\">HTML Living Standard: Server-Sent Events</a>：SSE 事件与重连语义</li><li><a href=\"https://streams.spec.whatwg.org/\" target=\"_blank\" rel=\"noopener\">WHATWG Streams Standard</a>：流、背压与取消</li><li><a href=\"https://encoding.spec.whatwg.org/\" target=\"_blank\" rel=\"noopener\">Encoding Standard</a>：UTF-8 增量解码</li><li><a href=\"https://arxiv.org/abs/2211.17192\" target=\"_blank\" rel=\"noopener\">Speculative Decoding</a>：生成延迟优化与流式阶段关系</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
